// delivery · кейсы dlv-04, dlv-05 (.qa/tests/delivery/) — נהג через «כניסה כעובד» под «יוסי הנהג» из admin-сессии.
// admin.json не перезаписывается; в конце — «חזרה לחשבון הניהול».
import { test, expect, Page } from '@playwright/test';
import * as path from 'path';

const auth = (role: string) => path.resolve(__dirname, '../../../auth', `${role}.json`);
test.use({ storageState: auth('admin') });

const DRIVER = 'יוסי הנהג';

async function impersonate(page: Page, employee: string) {
  await page.goto('/team');
  await expect(page.getByRole('heading', { name: 'צוות והרשאות' })).toBeVisible({ timeout: 20_000 });
  const row = page
    .locator('div')
    .filter({ hasText: employee })
    .filter({ has: page.getByRole('button', { name: 'פעולות' }) })
    .last();
  await row.getByRole('button', { name: 'פעולות' }).click();
  await page.getByRole('menuitem', { name: 'כניסה כעובד' }).click();
  await page.getByRole('dialog').getByRole('button', { name: 'כניסה', exact: true }).click();
  await expect(page.getByText(`מחובר/ת כרגע בתור ${employee} — כניסה כעובד פעילה`)).toBeVisible({ timeout: 20_000 });
}

async function backToAdmin(page: Page) {
  await page.getByRole('button', { name: 'חזרה לחשבון הניהול' }).click();
  await expect(page.getByText('מפיץ ראשי').first()).toBeVisible({ timeout: 20_000 });
}

test.describe('delivery — נהג (כניסה כעובד)', () => {
  test('נהג: טקסט ההסבר משקף את הזרימה, אין «הפריטים במשלוח», תעודה של נהג אחר חסומה #6a70ae75 #6a70b0b7 @desktop', async ({ page }) => {
    // href תעודה, назначенной другому водителю (не יוסי), — берём с доски админа.
    await page.goto('/delivery');
    await expect(page.getByRole('heading', { level: 1, name: 'משלוחים' })).toBeVisible({ timeout: 20_000 });
    const foreign = page.getByRole('link', { name: /^תעודת משלוח · הזמנה #\d+/ });
    let foreignHref: string | null = null;
    const n = await foreign.count();
    for (let i = 0; i < n; i++) {
      const card = foreign.nth(i).locator('..');
      const txt = await card.innerText();
      if (!txt.includes(DRIVER) && !txt.includes('טרם שויך נהג')) { foreignHref = await foreign.nth(i).getAttribute('href'); break; }
    }

    await impersonate(page, DRIVER);
    await expect(page).toHaveURL(/\/delivery/);
    await expect(page.getByText(DRIVER).first()).toBeVisible();
    await expect(page.getByRole('heading', { level: 1, name: 'משלוחים' })).toBeVisible();
    await expect(page.getByText('רשימת החלוקה שלך. לחצו על הזמנה לפתיחת תעודת המשלוח; «יצאה למשלוח» ביציאה מהמחסן, ו«סופקה» לאחר המסירה ללקוח')).toBeVisible();
    await expect(page.getByText('הפריטים במשלוח')).toHaveCount(0);
    await expect(page.getByRole('link', { name: 'תמחור' })).toHaveCount(0);

    const own = page.getByRole('link', { name: /^תעודת משלוח · הזמנה #\d+/ });
    if (await own.count()) {
      // Есть назначенные заказы — клик открывает תעודה без цен.
      await own.first().click();
      await expect(page.getByRole('heading', { level: 1, name: /^תעודת משלוח · הזמנה #\d+/ })).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText('פרטי משלוח')).toBeVisible();
      await expect(page.getByRole('columnheader', { name: 'מק"ט' })).toBeVisible();
      await expect(page.getByText(/₪/)).toHaveCount(0);
      await expect(page.getByRole('button', { name: 'הדפסה / PDF' })).toBeVisible();
      await page.getByRole('button', { name: 'חזרה למשלוחים' }).click();
    } else {
      await expect(page.getByRole('heading', { name: 'אין משלוחים פתוחים' })).toBeVisible();
      await expect(page.getByText('כשישויכו אליך הזמנות הן יופיעו כאן, עם הכתובת והפריטים.')).toBeVisible();
    }

    if (foreignHref) {
      await page.goto(foreignHref);
      await expect(page.getByText('תעודת המשלוח לא נמצאה — ההזמנה אינה משויכת אליך.')).toBeVisible({ timeout: 20_000 });
      await expect(page.getByText(/₪/)).toHaveCount(0);
      await expect(page.getByRole('button', { name: 'חזרה למשלוחים' })).toBeVisible();
    }

    await backToAdmin(page);
  });
});
